output_text:
[
  {
    "id": "take_entry_cart",
    "text": "A shopper is obliged to take the cart stationed at the entrance before completing the trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "has_cart": "hasCart"
      },
      "events": {
        "pickup_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart",
              "PICKUP_CART"
            ]
          },
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entrance_cart"
    }
  },
  {
    "id": "no_hand_shopping",
    "text": "Required shelf items must not be carried by hand; they may be picked up only while the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "carrying_by_hand": "handFull"
      },
      "events": {
        "hand_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "has_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "hand_pickup"
        ]
      }
    }
  },
  {
    "id": "return_cart_top_left",
    "text": "Before leaving, the shopper is obliged to park the cart at the designated top-left return bay.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "has_cart": "hasCart",
        "cart_returned": "cartAt(0,1)"
      },
      "events": {
        "return_cart_at_bay": {
          "pre": {
            "and": [
              "return_bay",
              "has_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_at_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is forbidden to exit the supermarket while still holding or pushing the cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "at_exit": "at(9,5)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at_exit",
          "has_cart",
          "EXIT"
        ]
      }
    }
  },
  {
    "id": "leave_cart_only_bay",
    "text": "Leaving a cart is permitted only at the top-left cart-return bay.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "LEAVE_CART",
          {
            "not": "return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_checkout_zone",
    "text": "Carts are prohibited on the checkout and exit approach, so the shopper must walk through that zone without the cart.",
    "abstraction": {
      "state_properties": {
        "checkout_exit_zone": {
          "or": [
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "has_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "checkout_exit_zone",
          "has_cart"
        ]
      }
    }
  },
  {
    "id": "after_item_return_cart",
    "text": "After any item has been picked up into the cart, the shopper is obliged eventually to perform a cart-return action.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "return_bay": "at(0,1)",
        "cart_returned": "cartAt(0,1)"
      },
      "events": {
        "cart_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "has_cart"
            ]
          },
          "post": "has_cart"
        },
        "return_cart_at_bay": {
          "pre": {
            "and": [
              "return_bay",
              "has_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_item_pickup",
      "discharge": "return_cart_at_bay"
    }
  },
  {
    "id": "must_park_when_at_bay",
    "text": "When the shopper reaches the top-left return bay with a cart, moving away with the cart is forbidden; the cart should be left there.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "has_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "return_bay",
          "has_cart",
          {
            "or": [
              "N",
              "S",
              "E",
              "W"
            ]
          }
        ]
      }
    }
  }
]
